export const getGetDashboardSummaryUrl = (params?: GetDashboardSummaryParams) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {
    if (value !== undefined) {
      normalizedParams.append(key, value === null ? "null" : String(value));
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0
    ? `/v1/dashboard/summary?${stringifiedParams}`
    : `/v1/dashboard/summary`;
};

/**
 * 購入・商品を横断した集計を 1 レスポンスに合成して返します（1 画面 1 API）。認証必須で、管理者（admin）のみ
 * 実行できます。管理者でなければ 403 で拒否します。数値カード向けの集計値のみを返し、一覧・時系列は含みません。
 * 集計対象期間は orderedAfter / orderedBefore が指す半開区間 [orderedAfter, orderedBefore) です。
 * いずれも省略でき、両方省略した場合は全期間を集計します。orderedBefore が orderedAfter 以前
 * （同値を含む）の場合は 400 を返します。
 * 売上（salesAmount / salesCount）はキャンセル済みの購入を除外し未払いの購入を含みます。一方
 * purchaseStatusCounts はキャンセル済みも 1 ステータスとして含むため、両者の母集団は一致しません。
 * 商品数は期間に依存しないマスタの現在値です。金額は USD セント単位の整数です。
 * 対象データがない場合はエラーではなくゼロ値（各件数・金額 0・内訳は空配列）を返します。
 * 本 op 自体は DB の集計 SELECT のみで外部依存を持ちませんが、認証段（外部 IdP の JWKS 参照）の
 * 一時障害で応答不能となり得るため、認証必須 op の先例に倣い 503 を宣言します。
 * @summary admin ダッシュボードの横断集計の取得
 */
export const getDashboardSummary = async (
  params?: GetDashboardSummaryParams,
  options?: RequestInit,
): Promise<getDashboardSummaryResponse> => {
  const res = await fetch(getGetDashboardSummaryUrl(params), {
    ...options,
    method: "GET",
  });

  const body = [204, 205, 304].includes(res.status) ? null : await res.text();

  const data: getDashboardSummaryResponse["data"] = body ? JSON.parse(body) : {};
  return { data, status: res.status, headers: res.headers } as getDashboardSummaryResponse;
};

